#!/usr/bin/env node
/**
 * Writes data/test-inventory.json — every unit and E2E test by name, grouped
 * by file — which /architecture/tests renders.
 *
 *   node scripts/test-inventory.mjs <vitest-json-report>
 *
 * `npm run build` runs it straight after the unit suite, from that run's JSON
 * report, so the list on the live site is regenerated by the build that
 * deployed it. The E2E list comes from `playwright test --list`, which reads
 * the specs without launching a browser or a server.
 *
 * The output is deterministic — files sorted, tests in source order, no times
 * or durations — so the committed copy only changes when a test does. CI
 * fails if the committed copy differs from what its build produced, which
 * keeps local dev (which doesn't regenerate it) honest too.
 */
import { execFileSync } from "node:child_process";
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

const root = process.cwd();
const [report] = process.argv.slice(2);
if (!report) {
  console.error("Usage: node scripts/test-inventory.mjs <vitest-json-report>");
  process.exit(2);
}

const rel = (file) => path.relative(root, path.resolve(root, file)).split(path.sep).join("/");
const byFile = (a, b) => a.file.localeCompare(b.file);

// ── Unit: from the Vitest run that just passed ──────────────────────────────

const vitest = JSON.parse(readFileSync(report, "utf8"));
const unit = vitest.testResults
  .map((f) => ({
    file: rel(f.name),
    tests: f.assertionResults.map((t) => ({
      name: [...t.ancestorTitles, t.title].join(" › "),
      ...(t.status === "skipped" || t.status === "pending" || t.status === "todo" ? { skipped: true } : {}),
    })),
  }))
  .sort(byFile);

// ── E2E: listed, not run ────────────────────────────────────────────────────

const listing = JSON.parse(
  execFileSync(path.join(root, "node_modules/.bin/playwright"), ["test", "--list", "--reporter=json"], {
    encoding: "utf8",
    maxBuffer: 32 * 1024 * 1024,
  })
);

function specsIn(suite, prefix = []) {
  const here = (suite.specs ?? []).map((s) => ({ line: s.line, name: [...prefix, s.title].join(" › ") }));
  const nested = (suite.suites ?? []).flatMap((s) => specsIn(s, [...prefix, s.title]));
  return [...here, ...nested].sort((a, b) => a.line - b.line);
}

const e2eDir = listing.config?.rootDir ?? path.join(root, "e2e");
const e2e = listing.suites
  .map((s) => ({
    file: rel(path.join(e2eDir, s.file)),
    tests: specsIn(s).map(({ name }) => ({ name })),
  }))
  .sort(byFile);

// ── Write ───────────────────────────────────────────────────────────────────

const count = (groups) => groups.reduce((n, g) => n + g.tests.length, 0);
const inventory = { unit, e2e };
writeFileSync(path.join(root, "data/test-inventory.json"), JSON.stringify(inventory, null, 2) + "\n");
console.log(
  `test inventory: ${count(unit)} unit tests in ${unit.length} files, ` +
    `${count(e2e)} E2E tests in ${e2e.length} files`
);
